<?php require 'includes/bootstrap.php';$u=login_required();$s=$pdo->prepare('SELECT * FROM transactions WHERE user_id=? ORDER BY id DESC LIMIT 8');$s->execute([$u['id']]);$tx=$s->fetchAll();$pageTitle='Dashboard';require 'includes/header.php';?><section class="welcome"><div><span class="tag">Verified financial profile</span><h1>Hello, <?=e($u['full_name'])?></h1><p>Monitor explainable fraud assessments and securely verify your identity.</p></div><a class="button" href="transaction.php">Assess transaction</a></section><section class="grid three"><article><small>Email status</small><h2>Verified</h2></article><article><small>Camera identity</small><h2><?=$u['photo_path']?'Enrolled':'Not enrolled'?></h2></article><article><small>Account role</small><h2><?=e(ucfirst($u['role']))?></h2></article></section><section class="card"><h2>Recent assessments</h2><div class="table"><table><tr><th>Beneficiary</th><th>Amount</th><th>Risk</th><th>Status</th><th>Date</th></tr><?php foreach($tx as $t):?><tr><td><?=e($t['beneficiary'])?></td><td>GHS <?=number_format((float)$t['amount'],2)?></td><td><span class="risk <?=e($t['risk_level'])?>"><?=e($t['risk_level'])?> <?=e((string)$t['risk_score'])?></span></td><td><?=e($t['status'])?></td><td><?=e($t['created_at'])?></td></tr><?php endforeach?></table></div><?php if(!$tx):?><p>No assessments yet.</p><?php endif?></section><?php require 'includes/footer.php';?>
